import fs from 'node:fs';import assert from 'node:assert/strict';import {createHash} from 'node:crypto';
const files=['backend-rust/src/types.rs','backend-rust/src/engine.rs','backend-rust/src/evaluation.rs','live-paper/rust-clock-v2.test.mjs','data/freeze-native-request-clock-20261004.mjs','data/archive-native-request-clock-first-20261004.mjs','data/verify-native-request-clock-20261004.mjs','data/native-request-clock-evidence-helpers-20261004.mjs','data/record-native-request-clock-20261004.mjs','data/native-request-clock-declaration-20261004.json','data/native-request-clock-milestone-20261004.json','data/native-request-clock-milestone-20261004-v1.json','data/prepare-native-request-clock-publication-20261004.mjs','docs/BAAL.md'];
const e=JSON.parse(fs.readFileSync('data/native-request-clock-milestone-20261004.json'));assert.equal(e.checks.nodePassed,21);assert.equal(e.checks.rustPassed,2);assert.equal(e.checks.skipped,0);assert.equal(e.checks.legacyHistoricalCardsExact,180);assert.equal(e.competitionOrders,0);assert.equal(e.profitabilityEstablished,false);assert.equal(e.services.collectorStatus,'running');
const elements=files.map(path=>{const content=fs.readFileSync(path,'utf8');assert(!/(?:ace_|sk-)[a-zA-Z0-9]{15,}|-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY|Authorization:\\s*Bearer [a-zA-Z0-9]/.test(content),'Secret-like content '+path);return{path,mode:'100644',type:'blob',content};});
const pack=JSON.stringify(elements);fs.writeFileSync('data/native-request-clock-publication-elements.json',pack);console.log(JSON.stringify({files:files.length,chars:pack.length,hash:createHash('sha256').update(pack).digest('hex')}));
